<script setup>
import { openFileInNewTab } from '../utils/openFile.js';
import { computed, ref } from 'vue';
import { roomList } from '../utils/roomDetails.js';
import { getImageUrl } from '../config/api.js';
const props = defineProps({ room: { type: Object, required: true }, occupantCount: { type: Number, default: 0 } });
const photos = computed(() => roomList(props.room.photos));
const groups = computed(() => [{label:'Free amenities',items:roomList(props.room.amenities_free ?? props.room.amenities)},{label:'Paid amenities',items:roomList(props.room.amenities_paid)}]);
const available = computed(() => Math.max(0, Number(props.room.capacity || 0) - props.occupantCount - Number(props.room.reserved_count || 0)));
const viewer = ref(null), photoIndex = ref(0), zoomed = ref(false);
const openPhoto = (index) => { photoIndex.value=index; zoomed.value=false; viewer.value.showModal(); };
const stepPhoto = (direction) => { photoIndex.value=(photoIndex.value+direction+photos.value.length)%photos.value.length;zoomed.value=false; };
</script>
<template>
  <section class="room-summary" aria-labelledby="room-information-heading">
    <div class="room-summary-gallery" v-if="photos.length">
      <button type="button" class="room-summary-cover" @click="openPhoto(0)" aria-label="Open main room photo"><img :src="getImageUrl(photos[0])" alt="Main room photo" /><span>{{ photos.length }} {{ photos.length === 1 ? 'photo' : 'photos' }}</span></button>
      <div class="room-summary-thumbnails"><button v-for="(photo,index) in photos.slice(1,3)" :key="photo" type="button" @click="openPhoto(index+1)" :aria-label="'Open room photo ' + (index+2)"><img :src="getImageUrl(photo)" :alt="'Room photo ' + (index+2)" /></button><button v-if="photos.length > 3" type="button" class="room-summary-more" @click="openPhoto(3)">+{{ photos.length-3 }} more</button></div>
    </div>
    <div v-else class="room-summary-no-photo"><i class="fa-regular fa-image" aria-hidden="true"></i><span>No room photos provided</span></div>
    <div class="room-summary-description"><p class="room-summary-kicker">Room overview</p><h2 id="room-information-heading">Room information</h2><p>{{ room.description || 'No room description provided.' }}</p><div v-for="group in groups" :key="group.label" class="room-summary-amenities"><h3><i :class="['fa-solid', group.label === 'Free amenities' ? 'fa-gift is-free' : 'fa-cart-shopping is-paid']" aria-hidden="true"></i>{{ group.label }}</h3><div v-if="group.items.length"><span v-for="item in group.items" :key="item">{{ item }}</span></div><p v-else>None listed.</p></div></div>
    <dl class="room-summary-facts"><div><i class="fa-solid fa-layer-group" aria-hidden="true"></i><dt>Floor</dt><dd>{{ room.floor_label || 'Not specified' }}</dd></div><div><i class="fa-solid fa-user-group" aria-hidden="true"></i><dt>Room type</dt><dd>{{ Number(room.capacity) > 1 ? 'Shared room' : 'Single room' }}</dd></div><div><i class="fa-solid fa-bed" aria-hidden="true"></i><dt>Capacity</dt><dd>{{ room.capacity }} {{ Number(room.capacity) === 1 ? 'bed' : 'beds' }}</dd></div><div><i class="fa-solid fa-image" aria-hidden="true"></i><dt>Photos</dt><dd>{{ photos.length }} uploaded</dd></div></dl>
    <div class="room-summary-rent"><p><i class="fa-solid fa-tags" aria-hidden="true"></i>Monthly rent</p><strong>&#8369;{{ Number(room.price || room.house_price || 0).toLocaleString('en-PH') }}</strong><span :class="available ? 'available' : 'full'"><i class="fa-solid fa-bed" aria-hidden="true"></i>{{ available ? available + ' of ' + room.capacity + ' beds available today' : (Number(room.reserved_count || 0) ? 'All beds occupied or reserved' : 'Room is full') }}</span></div>
  <aside class="room-today-summary" aria-label="Room availability today">
    <div class="room-today-heading"><span class="today-icon"><i class="fa-solid fa-bed" aria-hidden="true"></i></span><div><h3>Room availability today</h3><p>Future reservations are shown separately below.</p></div></div>
    <dl class="room-today-counts"><div><dt>Total beds</dt><dd>{{ room.capacity }}</dd></div><div><dt>Beds assigned</dt><dd>{{ occupantCount }}</dd></div><div v-if="Number(room.reserved_count)"><dt>Reserved for today</dt><dd>{{ room.reserved_count }}</dd></div><div class="today-available"><dt>Available today</dt><dd>{{ available }}</dd></div></dl>
    <p v-if="Number(room.upcoming_reserved_count)" class="room-future-explanation"><i class="fa-regular fa-calendar" aria-hidden="true"></i><span><strong>{{ room.upcoming_reserved_count }} upcoming reservation{{ Number(room.upcoming_reserved_count)===1 ? '' : 's' }}</strong> {{ Number(room.upcoming_reserved_count)===1 ? 'starts' : 'start' }} later. {{ available }} {{ available===1 ? 'bed is' : 'beds are' }} available <strong>today</strong>; availability on a future date depends on the reservations for that date.</span></p>
    <p v-else class="room-future-explanation">Beds assigned include started stays awaiting arrival confirmation. Always check the requested dates before accepting another booking.</p>
  </aside></section>
  <Teleport to="body"><dialog ref="viewer" class="owner-room-photo-viewer" aria-label="Room photos" @keydown.left.prevent="stepPhoto(-1)" @keydown.right.prevent="stepPhoto(1)">
    <header><span>Room {{ room.room_number }} / Photo {{ photoIndex+1 }} of {{ photos.length }}</span><div><button type="button" @click="zoomed = !zoomed">{{ zoomed ? 'Fit to screen' : 'Zoom in' }}</button><a v-if="photos.length" :href="getImageUrl(photos[photoIndex])" target="_blank" rel="noopener noreferrer" @click.prevent="openFileInNewTab(getImageUrl(photos[photoIndex]))">Open in new tab</a><button type="button" autofocus @click="viewer.close()">Close</button></div></header>
    <div :class="['owner-room-photo-stage',{zoomed}]"><img v-if="photos.length" :src="getImageUrl(photos[photoIndex])" :alt="'Room ' + room.room_number + ', photo ' + (photoIndex+1)" /></div><footer v-if="photos.length > 1"><button type="button" @click="stepPhoto(-1)">Previous photo</button><button type="button" @click="stepPhoto(1)">Next photo</button></footer>
  </dialog></Teleport>
